/** Build a rectangular polygon around a parcel center (GeoJSON [lng,lat]). */
export function parcelGeometry(p) {
  const half = p.geometryHalf ?? 0.0007
  const lat = p.coordinates.lat
  const lng = p.coordinates.lng
  return {
    type: 'Polygon',
    coordinates: [[
      [lng - half, lat - half],
      [lng - half, lat + half],
      [lng + half, lat + half],
      [lng + half, lat - half],
      [lng - half, lat - half],
    ]],
  }
}

